import { Rive, RuntimeLoader } from '@rive-app/canvas';
import { Asset } from 'expo-asset';
import React, { useEffect, useRef, useState } from 'react';

import type { Mood, Who, Zone } from './Laith';

/*
 * The Rive engine for Laith and the lioness (web build).
 *
 * assets/rive/laith.riv is generated by design/laith/build_riv.py. Each artboard has one state
 * machine, "Mood": a number input `mood` picks the mood, and the triggers `pat`, `tail` and `book`
 * play the touch reactions. The file also carries its own touch listeners, which are switched off
 * here because the app decides what a touch means (see Laith.tsx) and fires the trigger itself.
 */

export const RIVE_AVAILABLE = true;

const MOODS: Mood[] = ['idle', 'wait', 'happy', 'sad', 'cheer', 'listen', 'wave'];
const TRIGGER: Record<Zone, string> = { head: 'pat', tail: 'tail', book: 'book' };
const MACHINE = 'Mood';

let file: Promise<ArrayBuffer> | null = null;
/** The character file, fetched once and shared by every instance. */
function loadFile(): Promise<ArrayBuffer> {
  if (!file) {
    RuntimeLoader.setWasmUrl(Asset.fromModule(require('@rive-app/canvas/rive.wasm')).uri);
    // this file is driven through state-machine inputs by design; the runtime still supports them
    Rive.suppressDeprecationWarnings = ['state-machines-param', 'state-machine-inputs'];
    file = fetch(Asset.fromModule(require('../../assets/rive/laith.riv')).uri).then((res) => {
      if (!res.ok) throw new Error(`laith.riv: HTTP ${res.status}`);
      return res.arrayBuffer();
    });
    file.catch(() => {
      file = null; // allow a retry on the next mount
    });
  }
  return file;
}

export type RiveProps = {
  mood: Mood;
  size: number;
  who: Who;
  flip?: boolean;
  /** Filled in with a function that plays the reaction for a touched zone. */
  fire: React.MutableRefObject<((zone: Zone) => void) | null>;
  onReady: () => void;
  /** The runtime or the file could not be loaded: the caller falls back to the drawn version. */
  onFail: () => void;
};

export function LaithRive({ mood, size, who, flip, fire, onReady, onFail }: RiveProps) {
  const canvas = useRef<HTMLCanvasElement | null>(null);
  const rive = useRef<Rive | null>(null);
  const [ready, setReady] = useState(false);
  // Laith has a mirrored artboard whose book still reads; the lioness is simply flipped.
  const artboard = who === 'lioness' ? 'Lioness' : flip ? 'LaithMirror' : 'Laith';
  const callbacks = useRef({ onReady, onFail });
  callbacks.current = { onReady, onFail };

  useEffect(() => {
    let alive = true;
    let made: Rive | null = null;
    setReady(false);
    loadFile()
      .then((buffer) => {
        if (!alive || !canvas.current) return;
        made = new Rive({
          buffer: buffer.slice(0),
          canvas: canvas.current,
          artboard,
          stateMachines: MACHINE,
          autoplay: true,
          shouldDisableRiveListeners: true,
          onLoad: () => {
            if (!alive || !made) return;
            made.resizeDrawingSurfaceToCanvas();
            rive.current = made;
            // development builds expose the instance on its canvas, for scripted checks of the state machine
            if (__DEV__ && canvas.current) (canvas.current as unknown as { __rive?: Rive }).__rive = made;
            setReady(true);
            callbacks.current.onReady();
          },
          onLoadError: () => {
            if (alive) callbacks.current.onFail();
          },
        });
      })
      .catch(() => {
        if (alive) callbacks.current.onFail();
      });
    return () => {
      alive = false;
      rive.current = null;
      try {
        made?.cleanup();
      } catch {
        // the instance may not have finished loading
      }
    };
  }, [artboard, size]);

  useEffect(() => {
    if (!ready) return;
    const inputs = rive.current?.stateMachineInputs(MACHINE) ?? [];
    const input = inputs.find((i) => i.name === 'mood');
    if (input) input.value = MOODS.indexOf(mood);
    fire.current = (zone) => inputs.find((i) => i.name === TRIGGER[zone])?.fire();
    return () => {
      fire.current = null;
    };
  }, [mood, ready, fire]);

  return React.createElement('canvas', {
    ref: canvas,
    width: size * 2,
    height: size * 2,
    style: { width: size, height: size, display: 'block', transform: who === 'lioness' && flip ? 'scaleX(-1)' : undefined },
  });
}
